WITH filtered AS (SELECT *, CASE WHEN status IN ('REFUNDED', 'FAILED') THEN 'Group A' ELSE 'Other' END status_group, COALESCE(method, 'DIRECT') method_filled FROM payments WHERE paid_at >= TO_DATE('2023-08-09')), gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM filtered), sessionized AS (SELECT id, method, paid_at, method_filled, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT DATE_TRUNC('MONTH', paid_at) AS activity_month, DATE_TRUNC('WEEK', paid_at) AS week_start, CASE WHEN session_no >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_no_tier, SUM(CASE WHEN method = 'card' THEN session_no ELSE 0 END) AS card_session_no, ROUND(SUM(session_no) / NULLIF(COUNT(CASE WHEN method = 'bank_transfer' THEN 1 END), 0), 2) AS session_no_per_bank_transfer FROM sessionized GROUP BY 1, 2, 3 HAVING card_session_no < 1000000
